CREATE TABLE IF NOT EXISTS lotes_repasses (id BIGSERIAL PRIMARY KEY,status TEXT NOT NULL CHECK(status IN('preparando','ativo','arquivado','rejeitado')),criado_em TIMESTAMPTZ DEFAULT now(),finalizado_em TIMESTAMPTZ,recursos JSONB DEFAULT '[]',metricas JSONB DEFAULT '{}',observacao TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_um_lote_repasses_ativo ON lotes_repasses((status)) WHERE status='ativo';
CREATE TABLE IF NOT EXISTS fatos_repasses_municipais(id BIGSERIAL PRIMARY KEY,lote_id BIGINT NOT NULL REFERENCES lotes_repasses(id) ON DELETE CASCADE,recurso_id TEXT NOT NULL,data_credito DATE,ano INTEGER NOT NULL,mes INTEGER NOT NULL CHECK(mes BETWEEN 1 AND 12),municipio TEXT NOT NULL,deducao_icms NUMERIC(18,2) DEFAULT 0,bruto_icms NUMERIC(18,2) DEFAULT 0,credito_icms NUMERIC(18,2) DEFAULT 0,deducao_ipi NUMERIC(18,2) DEFAULT 0,bruto_ipi NUMERIC(18,2) DEFAULT 0,credito_ipi NUMERIC(18,2) DEFAULT 0,deducao_ipva NUMERIC(18,2) DEFAULT 0,bruto_ipva NUMERIC(18,2) DEFAULT 0,credito_ipva NUMERIC(18,2) DEFAULT 0,chave_conteudo TEXT NOT NULL,UNIQUE(lote_id,chave_conteudo));
CREATE INDEX IF NOT EXISTS idx_repasses_ano_municipio ON fatos_repasses_municipais(lote_id,ano,municipio);
CREATE OR REPLACE VIEW vw_repasses_municipais_ativos AS SELECT f.* FROM fatos_repasses_municipais f JOIN lotes_repasses l ON l.id=f.lote_id AND l.status='ativo';
